}
function TakeDetails({ index }: { index: number }) {
  const e = useStore().explanations[index]
  if (e?.status !== 'done') return null
  const guess = e.answer ? ` · its guess ${e.answer === 'cancelled' ? 'cancelled' : `+${e.answer} min`}` : ''
