export function riskLevel(p: number): "low" | "mid" | "high" {
  if (p < 0.15) return "low"
  if (p < 0.4) return "mid"
  return "high"
}

/**
 * How a plan-fail probability is shown to a traveller. A good plan is framed
 * positively (green, "96% you make every change"); a shaky one names the risk
 * (amber, then red) so the number always reads in the direction of the colour.
 */
export type Outlook = { level: "low" | "mid" | "high"; colour: string; percent: number; short: string; unit: string; heading: string }
export function journeyOutlook(p: number): Outlook {
  const level = riskLevel(p)
  const colour = RISK_COLOUR[level]
  if (level === "low") {
    return { level, colour, percent: Math.round((1 - p) * 100), short: "you will make it", unit: "chance you will make it", heading: "This connection looks good." }
  }
  if (level === "mid") {
    return { level, colour, percent: Math.round(p * 100), short: "risk", unit: "estimated risk of missing a change", heading: "Give your day a backup plan." }
  }
  return { level, colour, percent: Math.round(p * 100), short: "risk", unit: "estimated risk of missing a change", heading: "Plan for a missed connection." }
}

/* ---------- headline count-up ---------- */
export function FailHeadline({ value, label }: { value: number; label?: string }) {
  const still = useReducedMotion()
  // A good plan counts up to "96% you make it", a shaky one to its risk; both start from zero.
  const outlook = journeyOutlook(value)
  const start = outlook.level === "low" ? 1 : 0
  const [shown, setShown] = useState(still ? value : start)
  const prev = useRef(start)
  useEffect(() => {
    if (still) {
      setShown(value)
      return
    }
    const controls = animate(prev.current, value, { duration: 1.2, ease: "easeOut", onUpdate: (v) => setShown(v) })
    prev.current = value
    return () => controls.stop()
  }, [value, still])
  const shownPercent = Math.round((outlook.level === "low" ? 1 - shown : shown) * 100)
  return (
    <div className="rounded-2xl border border-border bg-white p-4">
      <div className="text-xs uppercase tracking-wide text-muted-foreground">{label ?? outlook.unit}</div>
      <div className="headline-number mt-1 text-6xl font-semibold" style={{ color: outlook.colour }}>
        {shownPercent}
        <span className="text-3xl">%</span>
        <span className="ml-2 text-base font-medium">{outlook.short}</span>
      </div>
      <div className="mt-1 text-sm font-medium" style={{ color: outlook.colour }}>{outlook.heading}</div>
    </div>
  )
}

